#!/bin/bash
sed -i 's|</section>|</section>\n\n        <section className="mb-12">\n          <h2 className="text-xl text-cyan-300 mb-4">Featured Projects</h2>\n          {data.featuredProjects?.map((proj, idx) => (\n            <div key={idx} className="p-4 bg-white/5 border border-white/10 rounded mb-4">\n              <input className="w-full bg-transparent border-b border-white/20 mb-2 p-1 text-white outline-none" value={proj.title} onChange={e => { const n = [...data.featuredProjects!]; n[idx].title = e.target.value; setData({...data, featuredProjects: n}) }} />\n              <textarea className="w-full bg-transparent border-b border-white/20 mb-2 p-1 text-gray-400 outline-none" value={proj.description} onChange={e => { const n = [...data.featuredProjects!]; n[idx].description = e.target.value; setData({...data, featuredProjects: n}) }} />\n            </div>\n          ))}\n        </section>|g' src/Admin.tsx
